const input=$json??{};
const dealId=input.deal_id??null; const leadId=input.lead_id??null; const propertyId=input.property_id??null;
const route=String(input.route??'').toLowerCase(); const sellerResponse=String(input.seller_response??input.inbound_message??'').trim();
const timeoutAt=input.timeout_at??null; const now=new Date(); const timeoutReached=timeoutAt?now.getTime()>=new Date(timeoutAt).getTime():false;
const attempts=Number(input.reengagement_attempts??input.attempts??0); const maxAttempts=Number(input.max_reengagement_attempts??3);
const dnc=Boolean(input.dnc??input.do_not_contact??false); const blockers=Array.isArray(input.blockers)?input.blockers:[];
const idempotencyKey=String(input.idempotency_key??'').trim();
let status='needs_review'; let action='review'; let nextWorkflow='WF-351'; let reason='Follow-up decision requires review.';
if(dnc){status='dnc_blocked';action='stop';nextWorkflow='WF-126';reason='DNC protection prevents follow-up.';}
else if(blockers.length){status='blocked';action='stop';nextWorkflow='WF-126';reason='Active blocker prevents follow-up.';}
else if(sellerResponse){status='seller_response_received';action='classify_response';nextWorkflow='WF-342';reason='Seller response received; classify before any follow-up.';}
else if(!dealId||!leadId||!propertyId||!idempotencyKey){status='incomplete';action='repair_data';nextWorkflow='WF-351';reason='Required deal identity or idempotency data is missing.';}
else if(route==='awaiting_response'&&timeoutReached){
  if(attempts>=maxAttempts){status='max_attempts_reached';action='pause';nextWorkflow='WF-126';reason='Response timeout reached and maximum attempts are exhausted.';}
  else{status='followup_due';action='schedule_followup';nextWorkflow='WF-345';reason='Response timeout reached; controlled seller re-engagement is due.';}
}
else if(route==='awaiting_response'){status='still_waiting';action='wait';nextWorkflow='WF-351';reason='Response timeout has not been reached.';}
else{status='needs_review';action='review';nextWorkflow='WF-351';reason='Current route does not authorize autonomous follow-up.';}
const activity={activity_type:'seller_followup_decision_controller',subject:'WF-352 '+(dealId??'unknown-deal'),deal_id:dealId,lead_id:leadId,property_id:propertyId,status,action,next_workflow:nextWorkflow,seller_response_received:Boolean(sellerResponse),timeout_at:timeoutAt,timeout_reached:timeoutReached,reengagement_attempts:attempts,max_reengagement_attempts:maxAttempts,idempotency_key:idempotencyKey,dnc,blockers,reason};
return [{json:{...input,wf_id:'WF-352',status,action,next_workflow:nextWorkflow,timeout_reached:timeoutReached,reason,crm_activity:activity,evaluated_at:now.toISOString()}}];
